// Generated from the "Exercise form and stretching guide" research report (Nov 2026).
// Setup, execution and mistake cues are coaching guidance (ACE and common practice), paraphrased;
// safety notes, stretches and rules carry their evidence level and sources.
import type { Evidence } from '../types'
import type { SourceId } from './sources'

export type FormEvidence = Evidence | 'convention'

export interface Stretch {
  id: string
  name: string
  muscles: string[]
  howTo: string
  hold: string
  sets: string
  /** "after" = after training or on another day. */
  when: string
  evidence: FormEvidence
  sources: SourceId[]
}

export interface FormGuide {
  setup: string[]
  execution: string[]
  breathing: string
  mistakes: string[]
  /** An evidence-based safety note, when there is one. */
  safety?: { text: string; sources: SourceId[] }
  easier: string
  harder: string
  /** Stretch ids from STRETCHES. */
  stretches: string[]
}

export interface FormRule {
  id: string
  text: string
  evidence: FormEvidence
  /** Qualifier on the evidence level, e.g. "dose findings conflict". */
  note?: string
  sources: SourceId[]
}

