  squat: { setup: ["Bar on your upper back, hands just outside your shoulders.","Feet about shoulder-width, toes out a little.","Big breath, brace, step out of the rack."], execution: ["Sit down and back; knees follow your toes and may pass them.","Go as deep as you can with a neutral back and heels down.","Drive up through the whole foot, chest and hips rising together."], breathing: "Breathe in and brace at the top, breathe out past the hardest point.", mistakes: ["Knees caving in.","Heels lifting.","Low back rounding at the bottom under heavy load."], safety: { text: "Deep squats are safe for healthy knees if load builds gradually; limit depth with kneecap or PCL problems.", sources: ["pm_23821469","pm_11528346"] }, easier: "Goblet squat, or box squat to a set depth.", harder: "Pause squat (2 s at the bottom) or front squat.", stretches: ["quad_side_lying","figure4_glute"] },
  leg_press: { setup: ["Back and tailbone flat on the pad.","Feet flat, hip- to shoulder-width.","Set the seat so your knees start near 90°."], execution: ["Press through your whole foot, heels down.","Stop just short of locked knees.","Lower slowly until just before your hips lift or your back rounds."], breathing: "Out as you press, in as you lower.", mistakes: ["Locking the knees.","Going so deep your hips roll off the pad.","Heels lifting."], safety: { text: "Leg press to failure spiked blood pressure to about 320/250; exhale as you press, especially with high blood pressure.", sources: ["pm_3980383","pm_7741618"] }, easier: "Lighter load, shorter range.", harder: "Single-leg press.", stretches: ["quad_side_lying","figure4_glute"] },
  goblet: { setup: ["Hold one dumbbell upright at your chest, elbows in.","Feet about shoulder-width, toes slightly out."], execution: ["Sit down between your heels, chest up.","Lower until your hips pass your knees if your back stays neutral.","Push the floor away to stand."], breathing: "In and brace at the top, out on the way up.", mistakes: ["Weight drifting away from your chest.","Heels lifting.","Knees caving."], safety: { text: "Full-depth squats don't raise knee risk in healthy adults; use a pain-free depth if your knees hurt.", sources: ["pm_23821469"] }, easier: "Squat to a box or bench.", harder: "Heavier weight, or 2-3 s pause at the bottom.", stretches: ["quad_side_lying","figure4_glute"] },
  split_squat: { setup: ["Rear foot laces-down on a knee-height bench.","Front foot a long stride ahead.","Dumbbells at your sides, if using them."], execution: ["Drop your back knee straight down.","Front knee travels over your toes, front heel down.","Lower to about thigh-parallel, then drive up through the front foot."], breathing: "In on the way down, out on the way up.", mistakes: ["Front foot too close, so the heel lifts.","Front knee caving in.","Pushing off the back foot."], easier: "Split squat with both feet on the floor.", harder: "Add load.", stretches: ["hip_flexor_kneeling","quad_side_lying"] },
  bw_split_squat: { setup: ["Long staggered stance, feet hip-width apart side to side.","Back heel up, torso tall."], execution: ["Lower straight down until your back knee nearly touches.","Keep your front knee over your mid-foot or toes.","Push through your front heel to rise."], breathing: "In on the way down, out on the way up.", mistakes: ["Stance too narrow and wobbly.","Leaning far forward.","Front knee caving."], easier: "Shorter range, or hold a support.", harder: "Bulgarian split squat, or add dumbbells.", stretches: ["hip_flexor_kneeling","quad_side_lying"] },
  leg_ext: { setup: ["Line your knee up with the machine's pivot.","Pad on your lower shin, above the ankle.","Back on the pad, hold the handles."], execution: ["Straighten your knees smoothly to near full.","Squeeze for 1 s.","Lower over 2-3 s."], breathing: "Out as you lift, in as you lower.", mistakes: ["Swinging the weight.","Hips lifting off the seat.","Snapping into lock-out."], easier: "Lighter weight, partial range.", harder: "Single-leg, or 3 s lowering.", stretches: ["quad_side_lying","thomas_stretch"] },
  rdl: { setup: ["Stand tall, bar against your thighs, hands just outside your legs.","Feet hip-width, knees soft."], execution: ["Push your hips back and slide the bar down your thighs, back flat.","Stop at a strong hamstring stretch, usually about mid-shin.","Drive your hips forward to stand and squeeze your glutes."], breathing: "Breathe in and brace before lowering, out as you stand.", mistakes: ["Rounding your back to reach lower.","Bending the knees into a squat.","Bar drifting away from your legs."], safety: { text: "Keep your back flat under load; repeated loaded bending injured spinal discs in animal tests.", sources: ["pm_11114441"] }, easier: "Hip-hinge drill with a dowel along your back.", harder: "Pause at the bottom, or stand on a low plate.", stretches: ["hamstring_supine","figure4_glute"] },
  db_rdl: { setup: ["Dumbbells in front of your thighs, palms toward you.","Feet hip-width, knees soft."], execution: ["Hinge at the hips, dumbbells close to your legs.","Lower to about mid-shin with a flat back.","Push your hips forward to stand."], breathing: "In and brace before lowering, out on the way up.", mistakes: ["Rounding your back.","Dumbbells swinging forward.","Knees locked straight."], safety: { text: "Keep your back flat under load; repeated loaded bending injured spinal discs in animal tests.", sources: ["pm_11114441"] }, easier: "Lighter dumbbells, shorter range.", harder: "Single-leg RDL.", stretches: ["hamstring_supine","figure4_glute"] },
  leg_curl: { setup: ["Pick the seated machine if you have the choice.","Line your knee up with the pivot; pad on the lower shin, not the heel.","Seated, thigh pad snug; lying, hips pressed down."], execution: ["Curl your heels toward you past 90°.","Pause briefly.","Lower slowly to nearly straight."], breathing: "Out as you curl, in as you lower.", mistakes: ["Hips lifting or back arching.","Jerking the weight.","Rushing the lowering."], easier: "Lighter load.", harder: "One leg at a time, or 3-4 s lowering.", stretches: ["hamstring_supine"] },
  slider_curl: { setup: ["Lie on your back, heels on sliders or towels on a smooth floor.","Knees bent, arms by your sides; brace lightly."], execution: ["Lift your hips into a bridge.","Keep your hips up and slide your heels out over 3 s.","Pull your heels back in, hips high."], breathing: "In as you slide out, out as you pull in.", mistakes: ["Hips sagging as your legs straighten.","Arching your low back.","Sliding out too fast."], easier: "Slide out only, then drop your hips and reset.", harder: "Single-leg, or arms crossed on your chest.", stretches: ["hamstring_supine"] },
  single_rdl: { setup: ["Stand on one leg, knee soft; hold a wall at first.","Weight in the opposite hand, if using one.","Hips square to the floor."], execution: ["Hinge at the standing hip as your free leg reaches back.","Lower until your torso is near level or the hamstring is fully stretched.","Drive your hip forward to stand."], breathing: "In and brace on the way down, out on the way up.", mistakes: ["Hips twisting open.","Rounding your back.","Locking the standing knee."], easier: "Kickstand RDL, back toe lightly on the floor.", harder: "Add a dumbbell or kettlebell.", stretches: ["hamstring_supine","figure4_glute"] },
  nordic: { setup: ["Kneel on a pad with your ankles anchored.","Body straight from knees to head, hands ready at your chest."], execution: ["Lean forward as slowly as you can, hips straight.","Resist all the way down (3-5 s), then catch yourself with your hands.","Push lightly off the floor to come back up."], breathing: "Breathe out steadily as you lower; don't hold your breath.", mistakes: ["Bending at the hips.","Dropping fast early in the rep.","Adding reps too quickly."], safety: { text: "Programs with Nordics cut hamstring injuries about in half; start with very few reps.", sources: ["van_dyk"] }, easier: "Band-assisted, or stop before your hands touch.", harder: "Slower lowering, or hold a plate at your chest.", stretches: ["hamstring_supine"] },
