  db_hip_thrust: { setup: ["Upper back on a bench, feet hip-width.","Dumbbell held on your hip crease."], execution: ["Drive through your heels until hips line up with knees and shoulders.","Squeeze your glutes for 1-2 s, chin tucked, ribs down.","Lower slowly."], breathing: "Out on the way up, in on the way down.", mistakes: ["Arching your back at the top.","Dumbbell rolling around.","Going too fast."], easier: "Floor glute bridge.", harder: "Barbell hip thrust, or single-leg.", stretches: ["figure4_glute","hip_flexor_kneeling"] },
  glute_bridge: { setup: ["Lie on your back, knees bent, feet flat and hip-width.","Brace lightly to flatten your low back."], execution: ["Breathe out and press through your heels to lift your hips.","Stop at a straight line from shoulders to knees.","Hold 1-2 s, then lower slowly."], breathing: "Out as you lift, in as you lower.", mistakes: ["Pushing so high your back arches.","Pushing through your toes.","Knees falling in or out."], easier: "Smaller range, shorter holds.", harder: "Single-leg bridge, or shoulders on a bench with weight.", stretches: ["figure4_glute","hip_flexor_kneeling"] },
  calf_raise: { setup: ["Balls of your feet on a step edge, heels off.","Knees straight, not locked.","Light hand support for balance."], execution: ["Lower your heels slowly to a full stretch; pause 1 s.","Rise as high as you can over your big and second toes.","Pause 1 s at the top."], breathing: "Out as you rise, in as you lower.", mistakes: ["Bouncing at the bottom.","Cutting the range short.","Rolling onto your outer toes."], easier: "Both feet on flat ground.", harder: "Single-leg on the step, or hold a dumbbell.", stretches: ["calf_wall_straight","calf_bent_knee"] },
  machine_calf: { setup: ["Standing machine, shoulders under pads, knees straight; seated, pad snug on lower thighs.","Balls of your feet on the platform edge, heels free."], execution: ["Lower to a full heel stretch and pause.","Press up to full height and pause.","Take about 2 s on the way down."], breathing: "Out as you rise, in as you lower.", mistakes: ["Bouncing out of the stretch.","Bending your knees to help on the standing machine.","Partial range."], easier: "Lighter load.", harder: "Single-leg, or a 2 s pause at the bottom.", stretches: ["calf_wall_straight","calf_bent_knee"] },
  wall_sit: { setup: ["Back flat on a wall, feet hip-width, about 1.5-2 ft out.","Toes forward or slightly out."], execution: ["Slide down until your knees are near 90°; higher is easier.","Hold with knees over ankles and weight through your heels.","Slide back up the wall to finish."], breathing: "Breathe steadily the whole hold; never hold your breath.", mistakes: ["Knees caving or drifting past your toes.","Hands pushing on your thighs.","Holding your breath."], safety: { text: "Keep breathing; breath-holding adds a lot to the blood-pressure rise during hard efforts.", sources: ["pm_7741618"] }, easier: "Higher position, or a ball behind your back.", harder: "Lower position, or single-leg.", stretches: ["quad_side_lying","figure4_glute"] },
  cable_crunch: { setup: ["Rope on a high pulley; kneel facing it, an arm's length away.","Hold the rope ends beside your head, hips over knees."], execution: ["Curl your ribs down toward your pelvis until your elbows reach mid-thigh.","Keep your hips still; the spine does the moving.","Pause 1 s, then uncurl over 2-3 s."], breathing: "Out as you curl down, in as you return.", mistakes: ["Sitting back at the hips instead of curling.","Pulling with your arms.","Too heavy and jerky."], easier: "Floor crunch, or a lighter stack.", harder: "Heavier load with 3-4 s lowering, or add a twist.", stretches: ["cobra","childs_pose"] },
  plank: { setup: ["Forearms down, elbows under shoulders.","Legs straight, toes tucked, feet hip-width."], execution: ["Brace your abs and squeeze your glutes; lift into one straight line.","Hold with hips level and shoulders away from your ears.","Start with 10-30 s; build to 30-60 s, then make it harder."], breathing: "Breathe steadily behind the brace; don't hold your breath.", mistakes: ["Low back sagging.","Hips too high.","Shrugging, or elbows off line with shoulders."], easier: "Knees down, or hands on a bench.", harder: "Elbows further forward with the pelvis tucked, or single-arm plank.", stretches: ["cobra","childs_pose"] },
  dead_bug: { setup: ["Lie on your back, arms up, hips and knees at 90°.","Brace gently all round and set your low back toward the floor."], execution: ["Slowly reach one arm overhead as the opposite leg straightens.","Stop just before your low back starts to arch.","Return over about 2 s and switch sides."], breathing: "Out as you reach, in as you return; keep breathing.", mistakes: ["Low back lifting off the floor.","Moving too fast.","Ribs flaring as the arm goes overhead."], easier: "Move only the legs, or only the arms.", harder: "Straighter legs, slower tempo, or a light weight in the hands.", stretches: ["hip_flexor_kneeling"] },
  hanging_raise: { setup: ["Hang from a bar, hands shoulder-width; ab straps are fine.","Shoulders gently pulled down, legs together, body still."], execution: ["Lift your knees toward your chest.","Keep curling so your pelvis tilts up toward your ribs.","Pause 1 s, then lower over 2-3 s without swinging."], breathing: "Out as your knees rise, in as you lower.", mistakes: ["Swinging for momentum.","Lifting the thighs with no pelvic curl.","Dropping fast."], safety: { text: "High hip-flexor demand may not suit some people with low back problems; use a lying reverse crunch instead.", sources: ["pm_16649890"] }, easier: "Captain's-chair knee raise, or lying reverse crunch.", harder: "Straight-leg raise, or toes-to-bar.", stretches: ["hip_flexor_kneeling","cobra"] },
